  for (name,sw,sh,w,h,n) in [("identity",32,32,32,32,500),("emoji",128,128,24,24,100),("upscale",16,16,64,64,500),("large_down",2048,2048,128,128,3),("max_output",1024,1024,1024,1024,3),("thin",1,16384,512,1,3),("wide",16384,1,1,512,3)] {
