   let data=(0..sw*sh*4).map(|i|((i*113+i/11)%256) as u8).collect();let image=Image::test_image(sw,sh,data);let input=pool.snapshot().used;
   if mode=="probe" {
    crate::scale_meter::start();let result=image.resize_premultiplied(w,h).unwrap();let(live,peak)=crate::scale_meter::stop();
    let checksum=result.iter().fold(0xcbf29ce484222325u64,|v,&b|(v^b as u64).wrapping_mul(0x100000001b3));let returned=pool.snapshot().used-input;let admitted=pool.snapshot().peak-input;
