   }else{
    drop(image.resize_premultiplied(w,h).unwrap());let start=std::time::Instant::now();
    for _ in 0..n{let result=image.resize_premultiplied(w,h).unwrap();std::hint::black_box(&result);drop(result);}
    eprintln!("SCALE_SAMPLE {{\"name\":\"{name}\",\"scale_drop_ns\":{},\"n\":{n}}}",start.elapsed().as_nanos()/n);
   }
   drop(image);assert_eq!(pool.snapshot().used,0);
  }
 }
